def simulate_natural_selection(population, generations, mutation_rate):
    import random

    def calculate_fitness(population):
        total_fitness = sum(population)
        return [value / total_fitness for value in population]

    def select_survivors(population, fitness):
        cumulative_fitness = sum(fitness)
        survivors = []
        for value, fit in zip(population, fitness):
            r = random.random() * cumulative_fitness
            if r < fit:
                survivors.append(value)
                cumulative_fitness -= r
            else:
                continue
        return survivors

    def apply_mutation(population):
        mutated_population = []
        for value in population:
            if random.random() < mutation_rate:
                value += random.choice([-1, 1])
            mutated_population.append(value)
        return mutated_population

    population = population.copy()
    for _ in range(generations):
        fitness = calculate_fitness(population)
        survivors = select_survivors(population, fitness)
        population = apply_mutation(survivors)

    return population

